      "content": "from __future__ import annotations
from typing import Sequence, Dict, Any
from metricore.latency_summary import summarize_latency
from metricore.percent_change import calculate_percent_change

def latency_regression(before_ms: Sequence[float], after_ms: Sequence[float], tolerance_pct: float = 10.0) -> Dict[str, Any]:
    b = summarize_latency(before_ms)
    a = summarize_latency(after_ms)
    p50_c = calculate_percent_change(b['p50'], a['p50'])
    p95_c = calculate_percent_change(b['p95'], a['p95'])
    p50_v = p50_c if p50_c is not None else 0.0
    p95_v = p95_c if p95_c is not None else 0.0
    return {
        'p50_change': p50_v,
        'p95_change': p95_v,
        'is_regression': p50_v > tolerance_pct or p95_v > tolerance_pct
    }"
  }
}
